5: import type { User } from '../generated';
6: 
7: class AuthService {
8:   private accessToken: string;
9: 
10:   private expiresIn: number;
11: 
12:   private userData: User | null;
13: 
14:   constructor(accessToken: string) {
15:     this.accessToken = accessToken;
16:     this.expiresIn = ACCESS_TOKEN_EXPIRATION;
17:     const data = localStorage.getItem('userData');
18:     this.userData = data ? JSON.parse(data) : null;
19:   }
20: 
21:   public getAccessToken(): string {
22:     return this.accessToken;
23:   }
24: 
25:   public setAccessToken(newValue: string): void {
26:     this.accessToken = newValue;
27:     this.setRefreshTokenTimeout();
28:   }
29: 
30:   public getAccessTokenExpiration(): number {
31:     return this.expiresIn;
32:   }
33: 
34:   public setAccessTokenExpiration(newValue: number): void {
35:     this.expiresIn = newValue;
36:   }
37: 
38:   public getUser(): User {
39:     return this.userData;
40:   }
41: 
42:   public setUser(newValue: User | null): void {
43:     this.userData = newValue;
44:   }
45: 
46:   public refreshToken = async (): Promise<void> => {
47:     try {
48:       if (window.location.pathname.startsWith('/auth')) {
49:         return;
50:       }
51:       const data = (await (
52:         await fetch(`${BACKEND_HOST}/refresh-token`, {
53:           method: 'POST',
54:           credentials: 'include',
55:           headers: {
56:             'Content-Type': 'application/json',
57:           },
58:           mode: 'cors',
59:           body: JSON.stringify({ data: null }),
60:         })
61:       ).json()) as RefreshTokenResponse | ErrorResponse;
62:       if ('accessToken' in data) {
63:         this.setAccessToken(data.accessToken);
64:         this.setAccessTokenExpiration(data.expiresIn);
65:       } else if ('status' in data && !window.location.pathname.startsWith('/auth')) {
66:         navigate('/feed');
67:       }
68:     } catch (error) {
69:       // eslint-disable-next-line no-console
70:       console.log(JSON.stringify(error));
71:     }
72:   };
73: 
74:   public setRefreshTokenTimeout(): void {
75:     setTimeout(() => {
76:       this.refreshToken();
77:     }, (ACCESS_TOKEN_EXPIRATION - 1) * 1000);
78:   }
79: }
